const locationId = 'Zwz4relUXVPxx8uohnjV';
const apiKey = 'pit-b278b3ad-96bd-41fb-ba03-9f927039eb28';
const baseUrl = 'https://services.leadconnectorhq.com';
const ids = {
  salesPipelineId: 'MThKauqlvnEFuFmAkyWX',
  salesDiscoveryStageId: '6f5aa304-a190-40da-8556-7c65bbc52733',
};

const headers = {
  Authorization: `Bearer ${apiKey}`,
  Version: '2021-07-28',
  Accept: 'application/json',
  'Content-Type': 'application/json',
};

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (typeof this !== 'undefined' && this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP not available in Code node runtime.');
}

function extractOpportunities(data) {
  if (Array.isArray(data?.opportunities)) return data.opportunities;
  if (Array.isArray(data?.data?.opportunities)) return data.data.opportunities;
  if (Array.isArray(data?.data)) return data.data;
  if (Array.isArray(data)) return data;
  return [];
}

function opportunityId(opp) {
  return opp?.id || opp?._id || '';
}

function pipelineIdOf(opp) {
  return opp?.pipelineId || opp?.pipeline_id || opp?.pipeline?.id || opp?.pipeline?._id || '';
}

function stageIdOf(opp) {
  return opp?.pipelineStageId || opp?.pipeline_stage_id || opp?.pipelineStage?.id || opp?.pipelineStage?._id || '';
}

function statusOf(opp) {
  return String(opp?.status || '').trim().toLowerCase();
}

function timestampOf(opp) {
  const raw = opp?.updatedAt || opp?.dateUpdated || opp?.createdAt || opp?.dateAdded || opp?.created_at || 0;
  const ts = Date.parse(raw);
  return Number.isFinite(ts) ? ts : 0;
}

try {
  await doHttpRequest.call(this, {
    method: 'POST',
    url: `${baseUrl}/contacts/${encodeURIComponent(contactId)}/tags`,
    headers,
    body: { tags: ['SQL'] },
    json: true,
  });
  sync.tag = 'added_or_kept';
} catch (err) {
  const code = err?.statusCode || err?.httpCode || 500;
  const body = err?.response?.body || err?.message || err;
  sync.tag = 'error';
  sync.tagError = `${code} ${JSON.stringify(body)}`;
}

try {
  const searchResult = await doHttpRequest.call(this, {
    method: 'GET',
    url: `${baseUrl}/opportunities/search?location_id=${encodeURIComponent(locationId)}&contact_id=${encodeURIComponent(contactId)}&limit=100`,
    headers,
    json: true,
  });

  const opportunities = extractOpportunities(searchResult).sort((a, b) => timestampOf(b) - timestampOf(a));
  const openOpportunities = opportunities.filter((opp) => statusOf(opp) === '' || statusOf(opp) === 'open');
  const salesOpportunity = openOpportunities.find((opp) => pipelineIdOf(opp) === ids.salesPipelineId);

  if (salesOpportunity) {
    if (stageIdOf(salesOpportunity) === ids.salesDiscoveryStageId) {
      sync.opportunity = 'already_in_sales_discovery_scheduled';
      sync.opportunityId = opportunityId(salesOpportunity);
    } else {
      await doHttpRequest.call(this, {
        method: 'PUT',
        url: `${baseUrl}/opportunities/${encodeURIComponent(opportunityId(salesOpportunity))}`,
        headers,
        body: {
          pipelineId: ids.salesPipelineId,
          pipelineStageId: ids.salesDiscoveryStageId,
        },
        json: true,
      });
      sync.opportunity = 'updated_existing_sales_opportunity';
      sync.opportunityId = opportunityId(salesOpportunity);
    }
  } else {
    const existingOpportunity = openOpportunities.find((opp) => pipelineIdOf(opp) !== ids.salesPipelineId);
    const desiredName = existingOpportunity?.name || `${fullName} - Sales`;

    if (existingOpportunity) {
      await doHttpRequest.call(this, {
        method: 'PUT',
        url: `${baseUrl}/opportunities/${encodeURIComponent(opportunityId(existingOpportunity))}`,
        headers,
        body: {
          pipelineId: ids.salesPipelineId,
          pipelineStageId: ids.salesDiscoveryStageId,
        },
        json: true,
      });
      sync.opportunity = 'moved_existing_opportunity_to_sales';
      sync.opportunityId = opportunityId(existingOpportunity);
    } else {
      const created = await doHttpRequest.call(this, {
        method: 'POST',
        url: `${baseUrl}/opportunities/`,
        headers,
        body: {
          locationId,
          contactId,
          name: desiredName,
          pipelineId: ids.salesPipelineId,
          pipelineStageId: ids.salesDiscoveryStageId,
          status: 'open',
        },
        json: true,
      });
      sync.opportunity = 'created_sales_opportunity';
      sync.opportunityId = opportunityId(created?.opportunity || created?.data || created);
    }
  }
} catch (err) {
  const code = err?.statusCode || err?.httpCode || 500;
  const body = err?.response?.body || err?.message || err;
  sync.opportunity = 'error';
  sync.opportunityError = `${code} ${JSON.stringify(body)}`;
}

textLines.push(`SQL tag sync: ${sync.tag}`);
textLines.push(`Opportunity sync: ${sync.opportunity}`);
if (sync.opportunityId) textLines.push(`Opportunity ID: ${sync.opportunityId}`);
if (sync.tagError) textLines.push(`Tag sync error: ${sync.tagError}`);
if (sync.opportunityError) textLines.push(`Opportunity sync error: ${sync.opportunityError}`);

return [{
  json: {
    text: textLines.join('\n'),
    sourcePayload: incoming,
    sync,
  }
}];

